import{_ as r,l as o,o as a,c as n,v as i,p as s,x as t,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"二项堆","description":"","frontmatter":{"title":"二项堆","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/binomial-heap.md","filePath":"cs/binomial-heap.md","lastUpdated":1789023840000}'),c={name:"cs/binomial-heap.md"};function _(h,e,u,B,b,f){const l=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=i('<h1 id="二项堆" tabindex="-1">二项堆 <a class="header-anchor" href="#二项堆" aria-label="Permalink to &quot;二项堆&quot;">​</a></h1><div class="epigraph"><p>一棵二项树 $B_k$ 有 $2^k$ 个节点；堆是不同秩的 $B_k$ 之林，合并像二进制加法进位。</p><footer>—— 据 Vuillemin, A Data Structure for Manipulating Priority Queues, CACM 1978；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/fibonacci-heap">上一课</a>用懒合并与标记换摊还 \\(O(1)\\) 减键。要理解「按度数合并」，更干净的模型是二项堆：每秩至多一棵，meld 最坏 \\(O(\\log n)\\)。本课不级联割。缺口是 Vuillemin 二项堆：形状由二进制唯一决定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(B_0\\) 单节点；\\(B_k\\) 是一个根挂上 \\(B_0,\\ldots,B_{k-1}\\)（或两个 \\(B_{k-1}\\) 按堆序链接）。节点数 \\(2^k\\)。二项堆 = 一组根，秩互异，各满足堆序。\\(n\\) 的二进制里有几个 1，林里就几棵树。meld：从小秩到大秩，同秩两棵链接成秩 \\(+1\\)，与加法进位相同。缺口是<strong>把可并堆做成二进制计数器</strong>，分析不必斐波那契。</p><p><span class="marginnote">CLRS 第 19 章先讲二项再讲斐波那契。insert 是 meld 一个 \\(B_0\\)，摊还可 \\(O(1)\\)，最坏 \\(O(\\log n)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>find-min：扫根表 \\(O(\\log n)\\) 棵。extract-min：摘最小根，其孩子是较小秩的二项堆，与剩余 meld。decrease-key：上滤，与二叉堆同，最坏 \\(O(\\log n)\\)，没有 Fib 的 \\(O(1)\\) 摊还。</p>',8)),(a(),s(p,null,{default:t(()=>[m(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BK%5B%22B_k%20%3D%20%E6%A0%B9%20%2B%20B_0..B_%7Bk-1%7D%22%5D%20--%3E%20FOREST%5B%22%E4%B8%8D%E5%90%8C%E7%A7%A9%E4%B9%8B%E6%9E%97%22%5D%0A%20%20MELD%5B%22meld%22%5D%20--%3E%20CARRY%5B%22%E5%90%8C%E7%A7%A9%E9%93%BE%E6%8E%A5%20%3D%20%E8%BF%9B%E4%BD%8D%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<p>与左偏：二项形状更死、证明更短；左偏树高也对数但不是 \\(2^k\\) 块。与 Fib：Fib 允许同秩多棵（根表懒），consolidate 才压成类似二项。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>链接：键大的根做键小的根的新孩子，秩加一。孩子表通常按秩有序，extract-min 时反转孩子链即可得合法二项堆。这是后课「可并堆 ADT」的标准实现之一。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把斜二项、或 Brodal 堆写进来。decrease-key 不是本结构的强项——那是 Fib 的动机。下一课把 meld/insert/extract-min/decrease-key 收成一张合同表，对照已出现的实现。</p><p>后课默认：按秩合并的林就是二项堆图像。可并堆 ADT 与表示分离。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>二项堆：二进制形状的可并堆，meld 如进位。</li><li>减键 \\(O(\\log n)\\)，不如 Fib 摊还。</li><li>下一课把可并堆合同钉死。</li><li>出处：Vuillemin, <em>CACM</em>, 1978；Cormen et al.。</li></ul>',8))])}const A=r(c,[["render",_]]);export{E as __pageData,A as default};
